INSERT INTO tools VALUES ('drip_emitter', 'Drip emitter', 'tool.drip', 'Waters the soil at the root zone and keeps foliage dry.');
INSERT INTO tools VALUES ('water_wand', 'Overhead water wand', 'tool.wand', 'Overhead water. Wets foliage; used only for directed mite washing.');
INSERT INTO tools VALUES ('stake', 'Plant stake', 'tool.stake', 'Supports the stem so foliage stays off the soil.');
INSERT INTO tools VALUES ('mulch', 'Mulch', 'tool.mulch', 'Covers soil to reduce splash onto lower leaves.');
INSERT INTO tools VALUES ('rake', 'Leaf rake', 'tool.rake', 'Gathers fallen leaves and residue.');
INSERT INTO tools VALUES ('trellis_tie', 'Trellis ties', 'tool.tie', 'Positions shoots on the trellis for airflow.');
INSERT INTO tools VALUES ('predator_release', 'Predator-release container', 'tool.predator', 'Releases predatory mites at a pest hotspot.');
INSERT INTO tools VALUES ('containment_bag', 'Containment bag', 'tool.bag', 'Encloses an infected plant before it is moved.');
INSERT INTO tools VALUES ('spade', 'Spade', 'tool.spade', 'Assisted removal of a whole plant.');
INSERT INTO tools VALUES ('transplant', 'Clean transplant', 'tool.transplant', 'Certified clean, suitable planting stock.');
INSERT INTO tools VALUES ('insect_mesh', 'Insect mesh', 'tool.mesh', 'Excludes whiteflies from clean planting material.');
