INSERT INTO methods VALUES ('tomato', 'early_blight', 'sanitation', 'Remove affected tissue and dispose of it', 'Reduces the spore source', 'Existing lesions on retained tissue stay.');
INSERT INTO methods VALUES ('tomato', 'early_blight', 'cultural', 'Water at the base, keep foliage dry', 'Reduces splash and leaf wetness', 'Does not remove existing infection.');
INSERT INTO methods VALUES ('tomato', 'early_blight', 'protect', 'Protective fungicide where justified', 'Protects healthy tissue during high-risk weather', 'Does not cure lesions; product and dose follow the local label.');
INSERT INTO methods VALUES ('tomato', 'early_blight', 'future', 'Rotation and resistant or tolerant varieties', 'Lowers risk in later crops', 'Not an immediate treatment.');
INSERT INTO steps VALUES ('tomato', 'early_blight', 'inspect', 10, 'Inspect', 'Inspect the lesions', 'Look for concentric, target-like spots|Note the yellow halo around each spot', 'inspect', 'magnifier', 'lesion_spot', 2, NULL, NULL, NULL, 0, 0, 'Noted.', 'Use the magnifier for this task.', 'Cut only the marked lesion areas. Healthy tissue and the petiole stay.', NULL);
INSERT INTO steps VALUES ('tomato', 'early_blight', 'underside', 20, 'Inspect', 'Turn the leaf over', 'Check the underside: the spots show through|No mould growth underneath', 'inspect', 'magnifier', 'leaf_underside', 1, NULL, NULL, NULL, 0, 0, 'Noted.', 'Use the magnifier for this task.', 'Cut only the marked lesion areas. Healthy tissue and the petiole stay.', NULL);
INSERT INTO steps VALUES ('tomato', 'early_blight', 'confirm', 30, 'Inspect', 'Confirm teaching case', 'Match the symptoms to the supplied case', 'choose', NULL, NULL, 1, NULL, NULL, NULL, 0, 0, 'Teaching case confirmed.', NULL, 'Cut only the marked lesion areas. Healthy tissue and the petiole stay.', NULL);
INSERT INTO step_options VALUES ('tomato', 'early_blight', 'confirm', 'correct', 1, 'Concentric brown spots with yellow halos (early blight)', 1, NULL, 'Confirmed. The symptoms match the supplied teaching case.');
INSERT INTO step_options VALUES ('tomato', 'early_blight', 'confirm', 'wrong1', 2, 'Olive-brown mould on the underside', 0, NULL, 'That describes leaf mold. These spots are concentric and on the upper surface.');
INSERT INTO step_options VALUES ('tomato', 'early_blight', 'confirm', 'wrong2', 3, 'Yellow, upward-curled young leaf', 0, NULL, 'Curling suggests a virus. This leaf carries concentric spots.');
INSERT INTO steps VALUES ('tomato', 'early_blight', 'cut', 40, 'Prepare', 'Cut out affected tissue', 'Cut only the marked lesion areas|Keep healthy tissue and the petiole|Then dispose and clean the shears', 'cut', 'shears', 'lesion_spot', 2, NULL, NULL, NULL, 1, 0, 'Removed. Next: dispose of it in Plant waste.', 'Use the pruning shears for this task.', 'Cut only the marked lesion areas. Healthy tissue and the petiole stay.', NULL);
INSERT INTO steps VALUES ('tomato', 'early_blight', 'dispose', 50, 'Prepare', 'Dispose of removed material', 'Place removed material in the lidded Plant waste container|Do not leave diseased material on the ground', 'dispose', NULL, 'disposal_bin', 1, NULL, NULL, NULL, 0, 0, 'Disposed of safely.', NULL, 'Put the removed material in the Plant waste container.', NULL);
INSERT INTO steps VALUES ('tomato', 'early_blight', 'clean_tools', 60, 'Prepare', 'Clean the tools', 'Clean and disinfect the tools at the Tool hygiene station|Follow the station procedure before touching healthy plants', 'clean_tool', NULL, 'sanitation_station', 1, NULL, NULL, NULL, 0, 0, 'Tools cleaned.', NULL, 'Clean the tools at the Tool hygiene station first.', NULL);
INSERT INTO steps VALUES ('tomato', 'early_blight', 'valve', 70, 'Treat', 'Switch to drip irrigation', 'Overhead watering splashes spores and bacteria onto leaves|Water the soil, keep leaves dry', 'control', NULL, 'irrigation_valve', 1, NULL, NULL, NULL, 0, 0, 'Drip irrigation ON.', NULL, 'Turn on the drip irrigation valve on the wall panel.', NULL);
INSERT INTO steps VALUES ('tomato', 'early_blight', 'assess', 80, 'Treat', 'Assess protection', 'High-risk teaching scenario|Warm, wet weather is forecast', 'choose', NULL, NULL, 1, NULL, NULL, NULL, 0, 0, NULL, NULL, 'Cut only the marked lesion areas. Healthy tissue and the petiole stay.', NULL);
INSERT INTO step_options VALUES ('tomato', 'early_blight', 'assess', 'opt1', 1, 'Protect healthy tissue with a crop-appropriate, labelled protectant', 1, 'protect', 'Protection covers healthy tissue only. It does not repair existing lesions.');
INSERT INTO step_options VALUES ('tomato', 'early_blight', 'assess', 'opt2', 2, 'Rely on sanitation and corrected conditions; monitor', 1, 'monitor', 'A valid choice: sanitation and drier conditions come first.');
INSERT INTO step_options VALUES ('tomato', 'early_blight', 'assess', 'opt3', 3, 'Spray the lesions to make them green again', 0, NULL, 'No treatment repairs dead tissue. Protection only shields healthy tissue.');
INSERT INTO steps VALUES ('tomato', 'early_blight', 'spray', 90, 'Treat', 'Protect healthy tissue', 'Cover the marked healthy tissue|Follow the label and treatment window|Old lesions will remain', 'spray', 'sprayer', 'healthy_tissue', 2, 'protect', NULL, NULL, 0, 0, 'Healthy tissue covered.', 'Use the hand sprayer (training) for this task.', 'Cover only the marked healthy tissue, not the lesions or the petiole.', NULL);
INSERT INTO steps VALUES ('tomato', 'early_blight', 'monitor_mark', 100, 'Treat', 'Plan monitoring', 'Mark the healthy tissue for the next check', 'inspect', NULL, 'healthy_tissue', 1, 'monitor', NULL, NULL, 0, 0, 'Monitoring planned.', NULL, 'Cut only the marked lesion areas. Healthy tissue and the petiole stay.', NULL);
INSERT INTO steps VALUES ('tomato', 'early_blight', 'wait', 110, 'Recheck', 'Advance to simulated follow-up', 'Time is compressed in this simulation|Inspect again at the next checkpoint', 'advance', NULL, NULL, 1, NULL, NULL, NULL, 0, 0, 'Simulated later observation.', NULL, 'Cut only the marked lesion areas. Healthy tissue and the petiole stay.', NULL);
INSERT INTO steps VALUES ('tomato', 'early_blight', 'check_new', 120, 'Recheck', 'Follow-up inspection', 'Compare a new leaf from the treated plant|Check for renewed spread', 'observe', NULL, 'new_leaf', 1, NULL, NULL, 'new_growth', 0, 0, 'Finding recorded.', NULL, 'Cut only the marked lesion areas. Healthy tissue and the petiole stay.', NULL);
INSERT INTO steps VALUES ('tomato', 'early_blight', 'check_old', 130, 'Recheck', 'Check the treated leaf', 'Old lesions remain|Dead tissue does not turn green', 'observe', NULL, 'lesion_spot', 1, NULL, NULL, 'old_lesions', 0, 0, 'Finding recorded.', NULL, 'Cut only the marked lesion areas. Healthy tissue and the petiole stay.', NULL);
INSERT INTO followups VALUES ('tomato', 'early_blight', 'new_growth', 'Inspect the new leaf', 'The new leaf is clean: no new lesions in this simulation.', 'If lesions appear on new leaves, repeat sanitation and reassess protection.');
INSERT INTO followups VALUES ('tomato', 'early_blight', 'old_lesions', 'Inspect the remaining lesions', 'Old lesions remain on the treated leaf; dead tissue does not recover.', 'Watch for new lesions near the old ones.');
INSERT INTO evidence VALUES ('tomato', 'early_blight', 'University of Minnesota Extension', 'https://extension.umn.edu/agriculture/specialty-crops/vegetable-farming/disease-management/early-blight-in-tomato-and-potato', 'Reviewed for this lesson', 'Upper Midwest, USA', 'Regional extension guidance; product choice follows local labels.');
INSERT INTO cases VALUES ('tomato', 'bacterial_spot', 'Tomato', 'Bacterial spot', 'Bacterial', 'A tomato leaf with bacterial spot after overhead watering and wet handling.', 'Managed', 'greenhouse', 'leafspecimen.tomato.bacterial_spot', 1.0, 'Xanthomonas causes small dark water-soaked spots; bacteria spread in splash, on hands and on tools.', 'Spread reduced: affected tissue removed, tools cleaned, drip irrigation on. Existing spots remain.', 2);
