INSERT INTO cases VALUES ('chilli', 'anthracnose', 'Chilli', 'Anthracnose', 'Fungal', 'A chilli leaf with anthracnose spots from a humid planting where fruit rot has also been seen.', 'Managed', 'greenhouse', 'leafspecimen.chilli.anthracnose', 1.0, 'Colletotrichum spp. cause small sunken spots with dark rings on leaves and serious fruit rot. The fungus is seed-borne and spreads in rain splash, favoured by high humidity.', 'Disease managed: affected tissue removed, splash reduced and healthy tissue protected. Existing spots remain.', 2);
