INSERT INTO cases VALUES ('soybean', 'mosaic_virus', 'Soybean', 'Mosaic virus', 'Viral', 'A soybean leaf from a stunted plant in a seed-production field; soybean mosaic virus was confirmed in the crop.', 'Replaced', 'field', 'leafspecimen.soybean.mosaic_virus', 1.0, 'Soybean mosaic virus enters fields on infected seed and aphids spread it within the crop. Leaves show light and dark green mosaic, puckering and distortion. Infected plants cannot be cured, and insecticides do not stop the virus.', 'The next crop starts from certified virus-free seed. The infected plant was removed from the seed field, not cured.', 2);
