INSERT INTO cases VALUES ('soybean', 'sudden_death_syndrome', 'Soybean', 'Sudden death syndrome', 'Fungal (soil-borne)', 'A soybean leaf with interveinal yellowing and browning from a field that was cool and wet at planting.', 'Replaced', 'field', 'leafspecimen.soybean.sudden_death_syndrome', 1.0, 'Fusarium virguliforme infects roots early in the season; a toxin moving to the leaves causes interveinal yellowing and death. Leaf sprays do not reach it, and affected plants cannot be saved this season.', 'The next crop starts with a tolerant variety and seed treatment. Affected plants were not cured.', 2);
