INSERT INTO cases VALUES ('wheat', 'rust', 'Wheat', 'Leaf rust', 'Fungal', 'A wheat leaf with orange-brown pustules from a susceptible variety before heading; volunteer wheat grew nearby.', 'Managed', 'field', 'leafspecimen.wheat.rust', 1.0, 'Puccinia triticina forms small orange-brown pustules on the upper leaf; wind carries spores far, and volunteer wheat bridges seasons. New races overcome resistance.', 'Remaining healthy tissue protected and the next crop planned. Existing pustules remain.', 2);
