INSERT INTO treatment_controls VALUES ('blueberry', 'rust', 'prevention', 40, 'resistance', 'Cultivar planning', 'Rotation, residue management, resistant varieties and clean stock for later crops.', 0, 10, 1, 0, 5, 10, 0.4, 0, 'Without planning, the next crop starts with the same risk.', 'Above the recommended range for this case.', 'Within the recommended range. Limitation: Susceptibility varies by cultivar; not an immediate treatment.');
INSERT INTO control_rules VALUES ('blueberry', 'rust', 'wet_spray', 'drip', 0, 3, 'protect', 5, 10, 0.25, 0, 'Spraying while overhead watering keeps the foliage wet: the coating washes off and splash keeps spreading the disease.');
