INSERT INTO treatment_controls VALUES ('rice', 'sheath_blight', 'protect', 10, 'protect', 'Protection at threshold', 'Share of the healthy tissue covered with a suitable, labelled protectant category. Abstract 0-10 scale: no product or dose is taught.', 0, 10, 1, 1, 6, 8, 1.2, 1, 'Too little coverage leaves healthy tissue exposed while conditions favour infection.', 'Over-application adds cost, residue and resistance risk without extra protection.', 'Within the recommended range. Limitation: Does not cure lesions; follow the local label.');
INSERT INTO treatment_controls VALUES ('rice', 'sheath_blight', 'airflow', 20, 'spacing', 'Canopy spacing and balanced nitrogen', 'Wider spacing and balanced nitrogen for a drier canopy.', 0, 10, 1, 1, 6, 8, 1.0, 1, 'Still, humid air keeps leaves wet long enough for new infections.', 'Excess airflow chills and dries the crop without extra disease benefit.', 'Within the recommended range. Limitation: Must be planned at planting.');
INSERT INTO treatment_controls VALUES ('rice', 'sheath_blight', 'sanitation', 30, 'sanitation', 'Weed and debris removal', 'How thoroughly affected tissue and debris are removed and disposed of (0 = nothing removed, 10 = every affected part removed and bagged).', 0, 10, 1, 1, 5, 7, 0.6, 0, 'Too little: affected tissue left in place keeps acting as an infection source.', 'More than this leaf needs: removing healthy tissue weakens the plant without extra benefit.', 'Within the recommended range. Limitation: Not an in-season cure.');
INSERT INTO control_rules VALUES ('rice', 'sheath_blight', 'dense', 'airflow', 0, 2, 'protect', 6, 10, 0.2, 0, 'In a very dense canopy the lesions keep climbing despite protection.');
INSERT INTO case_profile VALUES ('rice', 'tungro', 'Severe severity: about 55% of the leaf area is affected (simulated estimate).', 'Yellow to orange leaves|Stunted hills|Green leafhoppers in the field', 0.55, 0.53, 0.0, 0.0, 0.15, 0.0, 0.0, 0.0, 0.0, 'This leaf cannot be saved by treatment. Correct containment stops it acting as a source; recovery means replacing it with clean stock.');
