INSERT INTO case_profile VALUES ('wheat', 'blast', 'Moderate severity: about 35% of the leaf area is affected (simulated estimate).', 'Eye-shaped lesions with pale centres|Dark margins|Bleached spikes in warm, humid weather', 0.35, 0.7, 0.45, 0.18, 0.12, 0.6, 0.75, 0.6, 0.7, 'Dead lesion tissue does not turn green again. Good management dries the spots and stops their spread while the remaining green tissue recovers.');
INSERT INTO treatment_controls VALUES ('wheat', 'blast', 'protect', 10, 'protect', 'Preventive protection coverage', 'Share of the healthy tissue covered with a suitable, labelled protectant category. Abstract 0-10 scale: no product or dose is taught.', 0, 10, 1, 1, 6, 8, 1.2, 1, 'Too little coverage leaves healthy tissue exposed while conditions favour infection.', 'Over-application adds cost, residue and resistance risk without extra protection.', 'Within the recommended range. Limitation: Does not cure lesions or bleached spikes; follow the local label.');
INSERT INTO treatment_controls VALUES ('wheat', 'blast', 'prevention', 20, 'sowing', 'Sowing-date planning', 'Sowing so heading avoids warm, humid weather.', 0, 10, 1, 1, 6, 10, 0.8, 1, 'Without planning, the next crop starts with the same risk.', 'Above the recommended range for this case.', 'Within the recommended range. Limitation: For the next season.');
INSERT INTO treatment_controls VALUES ('wheat', 'blast', 'resistance', 30, 'resistance', 'Variety choice', 'A partially resistant variety.', 0, 10, 1, 1, 6, 10, 0.6, 0, 'Without planning, the next crop starts with the same risk.', 'Above the recommended range for this case.', 'Within the recommended range. Limitation: No variety is immune.');
INSERT INTO case_profile VALUES ('wheat', 'leaf_blight', 'Moderate severity: about 35% of the leaf area is affected (simulated estimate).', 'Dark brown oval blotches|Blotches merge and dry the leaf|Worst in late-sown, warm crops', 0.35, 0.7, 0.45, 0.18, 0.12, 0.6, 0.75, 0.6, 0.7, 'Dead lesion tissue does not turn green again. Good management dries the spots and stops their spread while the remaining green tissue recovers.');
INSERT INTO treatment_controls VALUES ('wheat', 'leaf_blight', 'protect', 10, 'protect', 'Flag-leaf protection coverage', 'Share of the healthy tissue covered with a suitable, labelled protectant category. Abstract 0-10 scale: no product or dose is taught.', 0, 10, 1, 1, 5, 7, 1.0, 1, 'Too little coverage leaves healthy tissue exposed while conditions favour infection.', 'Over-application adds cost, residue and resistance risk without extra protection.', 'Within the recommended range. Limitation: Does not cure blotches; follow the local label.');
INSERT INTO treatment_controls VALUES ('wheat', 'leaf_blight', 'prevention', 20, 'seed', 'Clean seed and timely sowing', 'Rotation, residue management, resistant varieties and clean stock for later crops.', 0, 10, 1, 1, 6, 10, 1.0, 1, 'Without planning, the next crop starts with the same risk.', 'Above the recommended range for this case.', 'Within the recommended range. Limitation: Prevention for the next crop.');
INSERT INTO treatment_controls VALUES ('wheat', 'leaf_blight', 'resistance', 30, 'resistance', 'Resistant variety choice', 'A resistant variety next season.', 0, 10, 1, 1, 6, 10, 0.6, 0, 'Without planning, the next crop starts with the same risk.', 'Above the recommended range for this case.', 'Within the recommended range. Limitation: For the next crop.');
INSERT INTO case_profile VALUES ('wheat', 'rust', 'Moderate severity: about 30% of the leaf area is affected (simulated estimate).', 'Small orange-brown pustules|Upper leaf surface|Spores travel far on the wind', 0.3, 0.74, 0.45, 0.16, 0.12, 0.6, 0.75, 0.6, 0.7, 'Dead lesion tissue does not turn green again. Good management dries the spots and stops their spread while the remaining green tissue recovers.');
INSERT INTO treatment_controls VALUES ('wheat', 'rust', 'protect', 10, 'protect', 'Flag-leaf protection coverage', 'Share of the healthy tissue covered with a suitable, labelled protectant category. Abstract 0-10 scale: no product or dose is taught.', 0, 10, 1, 1, 6, 8, 1.2, 1, 'Too little coverage leaves healthy tissue exposed while conditions favour infection.', 'Over-application adds cost, residue and resistance risk without extra protection.', 'Within the recommended range. Limitation: Does not cure pustules; follow the local label.');
INSERT INTO treatment_controls VALUES ('wheat', 'rust', 'prevention', 20, 'volunteer', 'Volunteer wheat control', 'Removing volunteer wheat that bridges seasons.', 0, 10, 1, 1, 6, 10, 0.8, 1, 'Without planning, the next crop starts with the same risk.', 'Above the recommended range for this case.', 'Within the recommended range. Limitation: Not an in-season cure.');
